mapper.select:
SELECT transmission_id, request_tracking_id, transmission_code, transmission_msg, transmission_time, transmission_url, transmission_param, transmission_result_data, resp_ctrl_cmd_code, resp_ctrl_cmd_msg, resp_ctrl_cmd_time FROM tracking_result_data_transmission_info WHERE 1=1
AND transmission_id = #{transmissionId}
AND request_tracking_id = #{requestTrackingId}
ORDER BY transmission_id
LIMIT #{start},#{end}

